IEnumerator Run() {
 var start=w.CompletedStepCount;var attempt=w.SimulationAttemptCount;
 while(w.CompletedStepCount<110 && w.State.Phase==Polarity.Model.LevelPhase.Running) yield return new WaitForFixedUpdate();
 yield return new WaitForEndOfFrame();
 var tex=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(@"D:\Code\Polarity\docs\verification\步骤9-预警画面.png",tex.EncodeToPNG());UnityEngine.Object.Destroy(tex);
