 while(w.State.Phase==Polarity.Model.LevelPhase.Running && w.CompletedStepCount<500) yield return new WaitForFixedUpdate();
 var before=w.CompletedStepCount;var shots=w.Turrets[0].ShotsFired;var hp=w.PlayerHealth.CurrentHealth;
 for(int i=0;i<30;i++)yield return new WaitForFixedUpdate();
 var result=new {warning,steps=w.CompletedStepCount-start,attempts=w.SimulationAttemptCount-attempt,w.FailedStepCount,w.SpawnedProjectileCount,w.ConsumedProjectileCount,w.ActiveProjectileCount,shots,phase=w.State.Phase.ToString(),hp,terminalSafe=w.State.Phase==Polarity.Model.LevelPhase.Running || (before==w.CompletedStepCount && hp==w.PlayerHealth.CurrentHealth && shots==w.Turrets[0].ShotsFired)};
 EditorApplication.isPaused=true;done.SetResult(JsonConvert.SerializeObject(result));
}
w.StartCoroutine(Run());return done.Task;

