using System.Collections;
using System.Threading.Tasks;
using System.Linq;
using System.Reflection;
using Polarity.Simulation;
using Polarity.Entities;
using Codely.Newtonsoft.Json;
var old=Object.FindObjectOfType<SimulationWorld>();
var flags=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Polarity/Prefabs/Actors/Projectile.prefab").GetComponent<Projectile>();
var shot=(Projectile)typeof(SimulationWorld).GetMethod("SpawnProjectile",flags).Invoke(old,new object[]{prefab,new Vector2(4,-3),Vector2.right,0f});
old.SetPhase(Polarity.Model.LevelPhase.Paused);
var done=new TaskCompletionSource<string>();
var runner=new GameObject("TemporaryRetryProbe");Object.DontDestroyOnLoad(runner);
// A bridge coroutine runner survives the scene; asynchronous yielding stays on Unity's thread.
async Task<string> Run() {
 bool requested=old.Level.RequestRestart();
 for(int i=0;i<1000;i++) {await Task.Delay(10);var current=Object.FindObjectOfType<SimulationWorld>();if(current!=null && current!=old && current.OwnsPhysics){
  EditorApplication.isPaused=true;
  var result=new {requested,oldDestroyed=old==null,shotDestroyed=shot==null,bodies=current.Bodies.Count,ids=current.Bodies.Select(b=>b.BodyId).ToArray(),projectiles=current.ActiveProjectileCount,spawned=current.SpawnedProjectileCount,consumed=current.ConsumedProjectileCount,budget=current.State.RemainingMarks,hp=current.PlayerHealth.CurrentHealth,shots=current.Turrets[0].ShotsFired,worlds=Object.FindObjectsOfType<SimulationWorld>().Length,phase=current.State.Phase.ToString(),mode=Physics2D.simulationMode.ToString()};Object.Destroy(runner);return JsonConvert.SerializeObject(result);
 }}throw new System.Exception("Restart timeout");
}
EditorApplication.isPaused=false;return Run();
